import { execSync } from 'child_process';
import fs from 'fs';
const W='';
const FILES={'assets/pet-form.js':'','assets/pet-form.css':'','assets/product-calc.js':'','includes/class-product-calc.php':''};
const TOKG=process.env.GH_TOKEN, REPO=process.env.GH_REPO||'raimis079-creator/petshop-bridge';
const U=process.env.WP_USER||'', P=(process.env.WP_APP_PASS||'').replace(/\s+/g,'');
const AUTH='-u "'+U+':'+P+'"';
function wj(m,path,body){fs.writeFileSync('/tmp/wb.json', JSON.stringify(body));
  return execSync('curl -sk --max-time 150 '+AUTH+' -X '+m+' -H "Content-Type: application/json" --data-binary @/tmp/wb.json "https://dev.avesa.lt/wp-json/'+path+'"',{maxBuffer:50e6,timeout:170000}).toString();}
function putB64(name,b64){const u='https://api.github.com/repos/'+REPO+'/contents/screenshots/'+name;let s='';
 for(let i=0;i<6;i++){try{const j=JSON.parse(execSync('curl -s -H "Authorization: Bearer '+TOKG+'" "'+u+'?n='+Math.random()+'"',{maxBuffer:50e6}).toString());if(j.sha)s=j.sha;}catch(e){}
  fs.writeFileSync('/tmp/pj.json',JSON.stringify({message:'r',content:b64,...(s?{sha:s}:{})}));
  const c=execSync('curl -s -o /dev/null -w "%{http_code}" -X PUT -H "Authorization: Bearer '+TOKG+'" -d @/tmp/pj.json "'+u+'"',{maxBuffer:50e6}).toString().trim();
  if(c==='200'||c==='201')return c; execSync('sleep 3');}return 'fail';}
const o={marker:'S287'}; let sid=null;
try{
  let mk=null;
  for(let a=0;a<3;a++){ try{ mk=wj('POST','code-snippets/v1/snippets',{name:'S287 '+Date.now(),code:Buffer.from(W,'base64').toString('utf8'),scope:'front-end',active:true,priority:5});
    if(mk && mk.indexOf('"id"')>=0) break; }catch(e){} execSync('sleep 8'); }
  try{sid=JSON.parse(mk).id;}catch(e){o.mk=String(mk).slice(0,120);}
  execSync('sleep 5');
  fs.writeFileSync('/tmp/payload.json', JSON.stringify({files:FILES}));
  for(let a=0;a<3;a++){ try{const r=execSync('curl -sk --max-time 120 -X POST -H "Content-Type: application/json" --data-binary @/tmp/payload.json "https://dev.avesa.lt/?ps_dep218=Dp218x"',{maxBuffer:20e6,timeout:140000}).toString();
    const j=r.slice(r.indexOf('{'),r.lastIndexOf('}')+1); o.write=j; if(j.includes('pet-form.js')&&j.includes('pet-form.css')) break; }catch(e){o.write='ERR '+a;} execSync('sleep 5'); }
  const g=(u)=>execSync('curl -sk --max-time 30 "'+u+'"',{maxBuffer:8e6}).toString();
  const base='https://dev.avesa.lt/wp-content/plugins/petshop-core/assets/';
  const jf=g(base+'pet-form.js'), cf=g(base+'pet-form.css'), pf=g(base+'product-calc.js');
  o.form_handoff = jf.indexOf('readHandoff')>=0 && jf.indexOf('handoffNote')>=0;
  o.form_return  = jf.indexOf('petshop_calc_saved')>=0;
  o.css_handoff  = cf.indexOf('.pspet-handoff')>=0;
  o.calc_pname   = pf.indexOf('product_name: PNAME')>=0;
  // produkto puslapyje data-pname
  const h=g('https://dev.avesa.lt/product/exclusion-hypoallergenic-sausas-sunu-maistas-su-arkliena-ir-bulvemis-m-l-12-kg/');
  const m=h.match(/data-pname="([^"]{0,60})/); o.pname_attr = m?m[1]:null;
  o.psku_attr = (h.match(/data-psku="([^"]*)"/)||[])[1];
}catch(e){ o.err=String(e).slice(0,250); }
try{ if(sid!=null) execSync('curl -sk --max-time 60 '+AUTH+' -X DELETE "https://dev.avesa.lt/wp-json/code-snippets/v1/snippets/'+sid+'"'); }catch(e){}
putB64('s287.json', Buffer.from(JSON.stringify(o)).toString('base64'));
console.log('done');
